import { parsePath, escapeKey } from './src/pathstringifier.js';

// Test escapeKey with backslash
console.log("escapeKey tests:");
console.log("escapeKey('b\\\\'):", escapeKey('b\\'));
console.log("escapeKey('a.b'):", escapeKey('a.b'));
console.log("escapeKey('a\\\\b'):", escapeKey('a\\b'));

// Test parsePath with the new mode
console.log("\nparsePath tests (legacy=true):");
try {
  console.log(parsePath('test\\\\.a.b', true));
} catch(e) {
  console.log("Error:", e);
}

