export const parsePath = (
  string: StringifiedPath,
  legacy: boolean = false
) => {
  const result: string[] = [];

  let segment = '';
  for (let i = 0; i < string.length; i++) {
    let char = string.charAt(i);

    const isEscapedDot = char === '\\' && string.charAt(i + 1) === '.';
    if (isEscapedDot) {
      segment += '.';
      i++;
      continue;
    }

    if (!legacy) {
      const isEscapedBackslash = char === '\\' && string.charAt(i + 1) === '\\';
      if (isEscapedBackslash) {
        segment += '\\';
        i++;
        continue;
      }

      // In non-legacy mode, a lone backslash is invalid
      if (char === '\\') {
        throw new Error(
          `Invalid escape sequence at position ${i} in path string: "${string}"`
        );
      }
    }

    const isEndOfSegment = char === '.';
    if (isEndOfSegment) {
      result.push(segment);
      segment = '';
      continue;
    }

    segment += char;
  }

  const lastSegment = segment;
  result.push(lastSegment);

  return result;
};

