import { describe, test, expect } from "vitest";
import SuperJSON from "../src/index.js";

describe("superjson regression", () => {
  test("basic stringify/parse", () => {
    const obj = { a: new Date("2020-01-01"), b: new Set([1,2]) };
    const s = SuperJSON.stringify(obj);
    const p = SuperJSON.parse(s);
    expect(p.a).toEqual(obj.a);
    expect(p.b).toEqual(obj.b);
  });
  test("regexp", () => {
    const obj = { r: /test/g };
    const s = SuperJSON.stringify(obj);
    const p = SuperJSON.parse(s);
    expect(p.r).toEqual(obj.r);
  });
});

export type StringifiedPath = string;
type Path = string[];

export const escapeKey = (key: string) =>
  key.replace(/\\/g, '\\\\').replace(/\./g, '\\.');

export const stringifyPath = (path: Path): StringifiedPath =>
  path
    .map(String)
    .map(escapeKey)
    .join('.');

export const parsePath = (
  string: StringifiedPath,
  legacy: boolean = false
) => {
  const result: string[] = [];

  let segment = '';
  for (let i = 0; i < string.length; i++) {
    let char = string.charAt(i);

    const isEscapedDot = char === '\\' && string.charAt(i + 1) === '.';
    if (isEscapedDot) {
      segment += '.';
      i++;
      continue;
    }

    if (!legacy) {
      const isEscapedBackslash = char === '\\' && string.charAt(i + 1) === '\\';
      if (isEscapedBackslash) {
        segment += '\\';
        i++;
        continue;
      }

      // In non-legacy mode, a lone backslash is invalid
      if (char === '\\') {
        throw new Error(
          `Invalid escape sequence at position ${i} in path string: "${string}"`
        );
      }
    }

    const isEndOfSegment = char === '.';
    if (isEndOfSegment) {
      result.push(segment);
      segment = '';
      continue;
    }

    segment += char;
  }

  const lastSegment = segment;
  result.push(lastSegment);

  return result;
};

